 public func send(_ url:String,_ body:J,token:String?=nil)async throws->J{let request=try post(url,body,token:token);let (data,response)=try await session.data(for:request);guard let response=response as? HTTPURLResponse,response.statusCode==200 else{throw HTTPFailure(code:(response as? HTTPURLResponse)?.statusCode ?? 0)};try require(data.count<=4*1024*1024,"La respuesta excede el tamaño permitido.");return try JSONDecoder().decode(J.self,from:data)}
